# simulate Rust BinaryHeap with key function
class Heap:
    def __init__(s, key): s.d=[]; s.key=key
    def le(s,a,b): return s.key(a) <= s.key(b)
    def push(s,x):
        s.d.append(x); s.sift_up(0, len(s.d)-1)
    def sift_up(s, start, pos):
        el = s.d[pos]
        while pos > start:
            parent = (pos-1)//2
            if s.key(el) <= s.key(s.d[parent]): break
            s.d[pos] = s.d[parent]; pos = parent
        s.d[pos] = el
        return pos
    def pop(s):
        item = s.d.pop()
        if s.d:
            item, s.d[0] = s.d[0], item
            s.sift_down_to_bottom(0)
        return item
    def sift_down_to_bottom(s, pos):
        end = len(s.d); start = pos
        el = s.d[pos]
        child = 2*pos+1
        while child <= end - 2:
            if s.key(s.d[child]) <= s.key(s.d[child+1]): child += 1
            s.d[pos] = s.d[child]; pos = child; child = 2*pos+1
        if child == end - 1:
            s.d[pos] = s.d[child]; pos = child
        s.d[pos] = el
        s.sift_up(start, pos)
