cat > /workspace/src/terminfo.rs <<'EOF'
//! Minimal terminfo database support: lookup, parsing of compiled entries and
//! parameterized string expansion.

use std::collections::HashMap;
use std::env;
use std::fs;
use std::path::{Path, PathBuf};

pub struct TermInfo {
    pub numbers: HashMap<&'static str, u32>,
    pub strings: HashMap<&'static str, Vec<u8>>,
}

const NUM_COLORS_IDX: usize = 13;

fn string_cap_name(idx: usize) -> Option<&'static str> {
    match idx {
        39 => Some("sgr0"),
        131 => Some("sgr"),
        297 => Some("op"),
        359 => Some("setaf"),
        360 => Some("setab"),
        _ => None,
    }
}

fn home_dir() -> Option<PathBuf> {
    if let Some(h) = env::var_os("HOME") {
        if !h.is_empty() {
            return Some(PathBuf::from(h));
        }
    }
    unsafe {
        let uid = libc::getuid();
        let pw = libc::getpwuid(uid);
        if pw.is_null() {
            return None;
        }
        let dir = (*pw).pw_dir;
        if dir.is_null() {
            return None;
        }
        let s = std::ffi::CStr::from_ptr(dir);
        use std::os::unix::ffi::OsStrExt;
        Some(PathBuf::from(std::ffi::OsStr::from_bytes(s.to_bytes())))
    }
}

fn default_dirs() -> Vec<PathBuf> {
    vec![
        PathBuf::from("/etc/terminfo"),
        PathBuf::from("/lib/terminfo"),
        PathBuf::from("/usr/share/terminfo"),
        PathBuf::from("/usr/lib/terminfo"),
        PathBuf::from("/boot/system/data/terminfo"),
    ]
}

fn find_entry(term: &str) -> Option<PathBuf> {
    let first = term.chars().next()?;
    let mut dirs: Vec<PathBuf> = Vec::new();
    if let Some(d) = env::var_os("TERMINFO") {
        dirs.push(PathBuf::from(d));
    }
    if let Some(mut h) = home_dir() {
        h.push(".terminfo");
        dirs.push(h);
    }
    if let Ok(list) = env::var("TERMINFO_DIRS") {
        for d in list.split(':') {
            if d.is_empty() {
                dirs.extend(default_dirs());
            } else {
                dirs.push(PathBuf::from(d));
            }
        }
    }
    dirs.extend(default_dirs());

    for dir in dirs {
        if fs::metadata(&dir).is_err() {
            continue;
        }
        let p = dir.join(first.to_string()).join(term);
        if fs::metadata(&p).is_ok() {
            return Some(p);
        }
        let p = dir.join(format!("{:x}", first as u32)).join(term);
        if fs::metadata(&p).is_ok() {
            return Some(p);
        }
    }
    None
}

fn rd16(b: &[u8], off: usize) -> Option<i32> {
    if off + 2 > b.len() {
        return None;
    }
    Some(i16::from_le_bytes([b[off], b[off + 1]]) as i32)
}

fn rd32(b: &[u8], off: usize) -> Option<i32> {
    if off + 4 > b.len() {
        return None;
    }
    Some(i32::from_le_bytes([b[off], b[off + 1], b[off + 2], b[off + 3]]))
}

fn parse(data: &[u8]) -> Option<TermInfo> {
    let magic = rd16(data, 0)? as u16;
    let wide = match magic {
        0o432 => false,
        0o1036 => true,
        _ => return None,
    };
    let names_size = rd16(data, 2)?;
    let bools = rd16(data, 4)?;
    let nums = rd16(data, 6)?;
    let strs = rd16(data, 8)?;
    let table = rd16(data, 10)?;
    if names_size < 0 || bools < 0 || nums < 0 || strs < 0 || table < 0 {
        return None;
    }
    let (names_size, bools, nums, strs, table) = (
        names_size as usize,
        bools as usize,
        nums as usize,
        strs as usize,
        table as usize,
    );
    if bools > 44 || nums > 39 || strs > 414 {
        return None;
    }
    let mut off = 12 + names_size;
    if off > data.len() {
        return None;
    }
    off += bools;
    if (names_size + bools) % 2 == 1 {
        off += 1;
    }
    let mut numbers = HashMap::new();
    let width = if wide { 4 } else { 2 };
    for i in 0..nums {
        let v = if wide { rd32(data, off + i * width)? } else { rd16(data, off + i * width)? };
        if i == NUM_COLORS_IDX {
            let absent = if wide { v == -1 } else { v == -1 };
            if !absent && v >= 0 {
                numbers.insert("colors", v as u32);
            }
        }
    }
    off += nums * width;
    let mut offsets = Vec::with_capacity(strs);
    for i in 0..strs {
        offsets.push(rd16(data, off + i * 2)?);
    }
    off += strs * 2;
    if off + table > data.len() {
        return None;
    }
    let tab = &data[off..off + table];
    let mut strings = HashMap::new();
    for (i, &o) in offsets.iter().enumerate() {
        if o == -1 {
            continue;
        }
        let name = match string_cap_name(i) {
            Some(n) => n,
            None => {
                if o == -2 {
                    continue;
                }
                // validate like a real parser would
                let ou = (o as u16) as usize;
                if ou > tab.len() || !tab[ou..].contains(&0) {
                    return None;
                }
                continue;
            }
        };
        if o == -2 {
            strings.insert(name, Vec::new());
            continue;
        }
        let ou = (o as u16) as usize;
        if ou > tab.len() {
            return None;
        }
        match tab[ou..].iter().position(|&b| b == 0) {
            Some(len) => {
                strings.insert(name, tab[ou..ou + len].to_vec());
            }
            None => return None,
        }
    }
    Some(TermInfo { numbers, strings })
}

impl TermInfo {
    pub fn from_env() -> Option<TermInfo> {
        let name = env::var("TERM").ok()?;
        let path = find_entry(&name)?;
        Self::from_path(&path)
    }

    fn from_path(p: &Path) -> Option<TermInfo> {
        let data = fs::read(p).ok()?;
        parse(&data)
    }
}

#[derive(Clone, Debug)]
enum Param {
    Words(Vec<u8>),
    Number(i32),
}

#[derive(Clone, Copy, PartialEq)]
enum FmtOp {
    Digit,
    Octal,
    LowerHex,
    UpperHex,
    Str,
}

#[derive(Clone, Copy, Default)]
struct Flags {
    width: usize,
    precision: usize,
    alternate: bool,
    left: bool,
    sign: bool,
    space: bool,
}

#[derive(Clone, Copy, PartialEq)]
enum FState {
    Flags,
    Width,
    Precision,
}

#[derive(Clone, Copy)]
enum State {
    Nothing,
    Delay,
    Percent,
    SetVar,
    GetVar,
    PushParam,
    CharConstant,
    CharClose,
    IntConstant(i32),
    FormatPattern(Flags, FState),
    SeekIfElse(usize),
    SeekIfElsePercent(usize),
    SeekIfEnd(usize),
    SeekIfEndPercent(usize),
}

fn format_param(val: Param, op: FmtOp, flags: Flags) -> Result<Vec<u8>, ()> {
    let mut s = match val {
        Param::Number(d) => match op {
            FmtOp::Digit => {
                if flags.sign {
                    format!("{:+01$}", d, flags.precision)
                } else if d < 0 {
                    format!("{:01$}", d, flags.precision + 1)
                } else if flags.space {
                    format!(" {:01$}", d, flags.precision)
                } else {
                    format!("{:01$}", d, flags.precision)
                }
            }
            FmtOp::Octal => {
                if flags.alternate {
                    format!("0{:01$o}", d, flags.precision.saturating_sub(1))
                } else {
                    format!("{:01$o}", d, flags.precision)
                }
            }
            FmtOp::LowerHex => {
                if flags.alternate && d != 0 {
                    format!("0x{:01$x}", d, flags.precision)
                } else {
                    format!("{:01$x}", d, flags.precision)
                }
            }
            FmtOp::UpperHex => {
                if flags.alternate && d != 0 {
                    format!("0X{:01$X}", d, flags.precision)
                } else {
                    format!("{:01$X}", d, flags.precision)
                }
            }
            FmtOp::Str => return Err(()),
        }
        .into_bytes(),
        Param::Words(s) => match op {
            FmtOp::Str => {
                let mut s = s;
                if flags.precision > 0 && flags.precision < s.len() {
                    s.truncate(flags.precision);
                }
                s
            }
            _ => return Err(()),
        },
    };
    if flags.width > s.len() {
        let n = flags.width - s.len();
        if flags.left {
            s.extend(std::iter::repeat(b' ').take(n));
        } else {
            let mut s_ = Vec::with_capacity(flags.width);
            s_.extend(std::iter::repeat(b' ').take(n));
            s_.extend(s);
            s = s_;
        }
    }
    Ok(s)
}

/// Expand a parameterized capability string.
pub fn expand(cap: &[u8], params: &[i32]) -> Result<Vec<u8>, ()> {
    let mut state = State::Nothing;
    let mut output = Vec::with_capacity(cap.len());
    let mut stack: Vec<Param> = Vec::new();
    let mut mparams: Vec<Param> = (0..9).map(|_| Param::Number(0)).collect();
    for (dst, src) in mparams.iter_mut().zip(params.iter()) {
        *dst = Param::Number(*src);
    }
    let mut sta = vec![Param::Number(0); 26];
    let mut dyn_vars = vec![Param::Number(0); 26];

    for &c in cap.iter() {
        let cur = c as char;
        let mut old_state = state;
        match state {
            State::Nothing => {
                if cur == '%' {
                    state = State::Percent;
                } else if cur == '$' {
                    state = State::Delay;
                } else {
                    output.push(c);
                }
            }
            State::Delay => {
                old_state = State::Nothing;
                if cur == '>' {
                    state = State::Nothing;
                }
            }
            State::Percent => {
                match cur {
                    '%' => {
                        output.push(c);
                        state = State::Nothing
                    }
                    'c' => match stack.pop() {
                        Some(Param::Number(0)) => output.push(128u8),
                        Some(Param::Number(c)) => output.push(c as u8),
                        Some(_) => return Err(()),
                        None => return Err(()),
                    },
                    'p' => state = State::PushParam,
                    'P' => state = State::SetVar,
                    'g' => state = State::GetVar,
                    '\'' => state = State::CharConstant,
                    '{' => state = State::IntConstant(0),
                    'l' => match stack.pop() {
                        Some(Param::Words(s)) => stack.push(Param::Number(s.len() as i32)),
                        Some(_) => return Err(()),
                        None => return Err(()),
                    },
                    '+' | '-' | '/' | '*' | '^' | '&' | '|' | 'm' => {
                        match (stack.pop(), stack.pop()) {
                            (Some(Param::Number(y)), Some(Param::Number(x))) => stack.push(Param::Number(match cur {
                                '+' => x.wrapping_add(y),
                                '-' => x.wrapping_sub(y),
                                '*' => x.wrapping_mul(y),
                                '/' => {
                                    if y == 0 {
                                        return Err(());
                                    }
                                    x.wrapping_div(y)
                                }
                                '|' => x | y,
                                '&' => x & y,
                                '^' => x ^ y,
                                'm' => {
                                    if y == 0 {
                                        return Err(());
                                    }
                                    x.wrapping_rem(y)
                                }
                                _ => unreachable!(),
                            })),
                            (Some(_), Some(_)) => return Err(()),
                            _ => return Err(()),
                        }
                    }
                    '=' | '>' | '<' | 'A' | 'O' => match (stack.pop(), stack.pop()) {
                        (Some(Param::Number(y)), Some(Param::Number(x))) => stack.push(Param::Number(
                            if match cur {
                                '=' => x == y,
                                '<' => x < y,
                                '>' => x > y,
                                'A' => x > 0 && y > 0,
                                'O' => x > 0 || y > 0,
                                _ => unreachable!(),
                            } {
                                1
                            } else {
                                0
                            },
                        )),
                        (Some(_), Some(_)) => return Err(()),
                        _ => return Err(()),
                    },
                    '!' | '~' => match stack.pop() {
                        Some(Param::Number(x)) => stack.push(Param::Number(match cur {
                            '!' if x > 0 => 0,
                            '!' => 1,
                            '~' => !x,
                            _ => unreachable!(),
                        })),
                        Some(_) => return Err(()),
                        None => return Err(()),
                    },
                    'i' => match (&mparams[0], &mparams[1]) {
                        (&Param::Number(x), &Param::Number(y)) => {
                            mparams[0] = Param::Number(x + 1);
                            mparams[1] = Param::Number(y + 1);
                        }
                        (_, _) => return Err(()),
                    },
                    'd' | 'o' | 'x' | 'X' | 's' => {
                        if let Some(arg) = stack.pop() {
                            let flags = Flags::default();
                            let op = match cur {
                                'd' => FmtOp::Digit,
                                'o' => FmtOp::Octal,
                                'x' => FmtOp::LowerHex,
                                'X' => FmtOp::UpperHex,
                                's' => FmtOp::Str,
                                _ => unreachable!(),
                            };
                            let res = format_param(arg, op, flags)?;
                            output.extend(res.iter().cloned());
                        } else {
                            return Err(());
                        }
                    }
                    ':' | '#' | ' ' | '.' | '0'..='9' => {
                        let mut flags = Flags::default();
                        let mut fstate = FState::Flags;
                        match cur {
                            ':' => (),
                            '#' => flags.alternate = true,
                            ' ' => flags.space = true,
                            '.' => fstate = FState::Precision,
                            '0'..='9' => {
                                flags.width = cur as usize - '0' as usize;
                                fstate = FState::Width;
                            }
                            _ => unreachable!(),
                        }
                        state = State::FormatPattern(flags, fstate);
                    }
                    '?' => (),
                    't' => match stack.pop() {
                        Some(Param::Number(0)) => state = State::SeekIfElse(0),
                        Some(Param::Number(_)) => (),
                        Some(_) => return Err(()),
                        None => return Err(()),
                    },
                    'e' => state = State::SeekIfEnd(0),
                    ';' => (),
                    _ => return Err(()),
                }
            }
            State::PushParam => {
                let d = cur as usize;
                if (b'1' as usize..=b'9' as usize).contains(&d) {
                    stack.push(mparams[d - '1' as usize].clone());
                } else {
                    return Err(());
                }
            }
            State::SetVar => {
                if cur.is_ascii_uppercase() {
                    if let Some(arg) = stack.pop() {
                        let idx = (cur as u8) - b'A';
                        sta[idx as usize] = arg;
                    } else {
                        return Err(());
                    }
                } else if cur.is_ascii_lowercase() {
                    if let Some(arg) = stack.pop() {
                        let idx = (cur as u8) - b'a';
                        dyn_vars[idx as usize] = arg;
                    } else {
                        return Err(());
                    }
                } else {
                    return Err(());
                }
            }
            State::GetVar => {
                if cur.is_ascii_uppercase() {
                    let idx = (cur as u8) - b'A';
                    stack.push(sta[idx as usize].clone());
                } else if cur.is_ascii_lowercase() {
                    let idx = (cur as u8) - b'a';
                    stack.push(dyn_vars[idx as usize].clone());
                } else {
                    return Err(());
                }
            }
            State::CharConstant => {
                stack.push(Param::Number(c as i32));
                state = State::CharClose;
            }
            State::CharClose => {
                if cur != '\'' {
                    return Err(());
                }
            }
            State::IntConstant(i) => {
                if cur == '}' {
                    stack.push(Param::Number(i));
                    state = State::Nothing;
                } else if let Some(digit) = cur.to_digit(10) {
                    match i.checked_mul(10).and_then(|i_ten| i_ten.checked_add(digit as i32)) {
                        Some(i) => {
                            state = State::IntConstant(i);
                            old_state = State::Nothing;
                        }
                        None => return Err(()),
                    }
                } else {
                    return Err(());
                }
            }
            State::FormatPattern(ref mut flags, ref mut fstate) => {
                old_state = State::Nothing;
                match (*fstate, cur) {
                    (_, 'd') | (_, 'o') | (_, 'x') | (_, 'X') | (_, 's') => {
                        if let Some(arg) = stack.pop() {
                            let op = match cur {
                                'd' => FmtOp::Digit,
                                'o' => FmtOp::Octal,
                                'x' => FmtOp::LowerHex,
                                'X' => FmtOp::UpperHex,
                                's' => FmtOp::Str,
                                _ => unreachable!(),
                            };
                            let res = format_param(arg, op, *flags)?;
                            output.extend(res.iter().cloned());
                            // will cause state to go to Nothing
                            old_state = State::FormatPattern(*flags, *fstate);
                        } else {
                            return Err(());
                        }
                    }
                    (FState::Flags, '#') => flags.alternate = true,
                    (FState::Flags, '-') => flags.left = true,
                    (FState::Flags, '+') => flags.sign = true,
                    (FState::Flags, ' ') => flags.space = true,
                    (FState::Flags, '0'..='9') => {
                        flags.width = cur as usize - '0' as usize;
                        *fstate = FState::Width;
                    }
                    (FState::Width, '0'..='9') => {
                        flags.width = flags.width.saturating_mul(10).saturating_add(cur as usize - '0' as usize);
                    }
                    (FState::Width, '.') | (FState::Flags, '.') => {
                        *fstate = FState::Precision;
                    }
                    (FState::Precision, '0'..='9') => {
                        flags.precision = flags.precision.saturating_mul(10).saturating_add(cur as usize - '0' as usize);
                    }
                    _ => return Err(()),
                }
                state = State::FormatPattern(*flags, *fstate);
            }
            State::SeekIfElse(level) => {
                if cur == '%' {
                    state = State::SeekIfElsePercent(level);
                }
                old_state = State::Nothing;
            }
            State::SeekIfElsePercent(level) => {
                if cur == ';' {
                    if level == 0 {
                        state = State::Nothing;
                    } else {
                        state = State::SeekIfElse(level - 1);
                    }
                } else if cur == 'e' && level == 0 {
                    state = State::Nothing;
                } else if cur == '?' {
                    state = State::SeekIfElse(level + 1);
                } else {
                    state = State::SeekIfElse(level);
                }
            }
            State::SeekIfEnd(level) => {
                if cur == '%' {
                    state = State::SeekIfEndPercent(level);
                }
                old_state = State::Nothing;
            }
            State::SeekIfEndPercent(level) => {
                if cur == ';' {
                    if level == 0 {
                        state = State::Nothing;
                    } else {
                        state = State::SeekIfEnd(level - 1);
                    }
                } else if cur == '?' {
                    state = State::SeekIfEnd(level + 1);
                } else {
                    state = State::SeekIfEnd(level);
                }
            }
        }
        if same_state(&state, &old_state) {
            state = State::Nothing;
        }
    }
    Ok(output)
}

fn same_state(a: &State, b: &State) -> bool {
    use State::*;
    match (a, b) {
        (Nothing, Nothing) => true,
        (Delay, Delay) => true,
        (Percent, Percent) => true,
        (SetVar, SetVar) => true,
        (GetVar, GetVar) => true,
        (PushParam, PushParam) => true,
        (CharConstant, CharConstant) => true,
        (CharClose, CharClose) => true,
        (IntConstant(x), IntConstant(y)) => x == y,
        (FormatPattern(_, _), FormatPattern(_, _)) => true,
        (SeekIfElse(x), SeekIfElse(y)) => x == y,
        (SeekIfElsePercent(x), SeekIfElsePercent(y)) => x == y,
        (SeekIfEnd(x), SeekIfEnd(y)) => x == y,
        (SeekIfEndPercent(x), SeekIfEndPercent(y)) => x == y,
        _ => false,
    }
}

/// A terminal output device driven by terminfo.
pub struct Terminal {
    pub ti: TermInfo,
    pub num_colors: u32,
}

impl Terminal {
    pub fn from_env() -> Option<Terminal> {
        let ti = TermInfo::from_env()?;
        let nc = if ti.strings.contains_key("setaf") && ti.strings.contains_key("setab") {
            ti.numbers.get("colors").copied().unwrap_or(0)
        } else {
            0
        };
        Some(Terminal { ti, num_colors: nc })
    }

    fn dim_if_necessary(&self, color: u32) -> u32 {
        if color >= self.num_colors && (8..16).contains(&color) {
            color - 8
        } else {
            color
        }
    }

    /// Returns the escape sequence to set the foreground color.
    pub fn fg(&self, color: u32) -> Result<Vec<u8>, ()> {
        let color = self.dim_if_necessary(color);
        if self.num_colors > color {
            match self.ti.strings.get("setaf") {
                Some(cap) => expand(cap, &[color as i32]),
                None => Err(()),
            }
        } else {
            Err(())
        }
    }

    /// Returns the escape sequence to reset attributes.
    pub fn reset(&self) -> Result<Vec<u8>, ()> {
        let cap = ["sgr0", "sgr", "op"].iter().filter_map(|c| self.ti.strings.get(*c)).next();
        match cap {
            Some(c) => expand(c, &[]),
            None => Err(()),
        }
    }
}
