//! Colored console output built on top of terminfo.

use crate::terminfo::Terminal;
use std::io::Write;

pub const RED: u32 = 9;
pub const GREEN: u32 = 10;
pub const YELLOW: u32 = 11;
pub const CYAN: u32 = 14;
pub const WHITE: u32 = 7;

#[derive(Clone, Copy, PartialEq)]
pub enum Stream {
    Out,
    Err,
}

pub struct Console {
    stream: Stream,
    term: Terminal,
    color: bool,
    current: Option<u32>,
}

pub fn fatal_exit(code: i32) -> ! {
    let _ = std::io::stdout().flush();
    let _ = std::io::stderr().flush();
    std::process::exit(code)
}

fn write_stream(stream: Stream, bytes: &[u8]) {
    let r = match stream {
        Stream::Out => std::io::stdout().write_all(bytes),
        Stream::Err => std::io::stderr().write_all(bytes),
    };
    if r.is_err() {
        fatal_exit(1);
    }
}

impl Console {
    pub fn new(stream: Stream, color: bool) -> Option<Console> {
        let term = Terminal::from_env()?;
        Some(Console { stream, term, color, current: None })
    }

    pub fn set_color(&mut self, color: u32) {
        if !self.color {
            return;
        }
        if self.current == Some(color) {
            return;
        }
        match self.term.fg(color) {
            Ok(seq) => {
                write_stream(self.stream, &seq);
                self.current = Some(color);
            }
            Err(_) => fatal_exit(1),
        }
    }

    /// Force the color escape even if the color seems to be already set.
    pub fn force_color(&mut self, color: u32) {
        match self.term.fg(color) {
            Ok(seq) => {
                write_stream(self.stream, &seq);
                self.current = Some(color);
            }
            Err(_) => fatal_exit(1),
        }
    }

    pub fn write(&mut self, color: u32, text: &str) {
        self.set_color(color);
        write_stream(self.stream, text.as_bytes());
    }

    pub fn write_bytes(&mut self, color: u32, text: &[u8]) {
        self.set_color(color);
        write_stream(self.stream, text);
    }

    pub fn flush(&mut self) {
        let r = match self.stream {
            Stream::Out => std::io::stdout().flush(),
            Stream::Err => std::io::stderr().flush(),
        };
        if r.is_err() {
            fatal_exit(1);
        }
    }

    pub fn reset(&mut self) {
        match self.term.reset() {
            Ok(seq) => {
                write_stream(self.stream, &seq);
                self.flush();
            }
            Err(_) => fatal_exit(1),
        }
    }
}
