//! Command line parsing that mimics the behavior of the clap 2 based
//! interface of the original tool.

use crate::config::Config;
use std::io::{IsTerminal, Write};

pub const VERSION: &str = "0.6.0";
pub const APP_NAME: &str = "ambr";

#[derive(Debug, Default, Clone)]
pub struct Opt {
    pub keyword: String,
    pub replacement: String,
    pub paths: Vec<String>,
    pub key_from_file: bool,
    pub rep_from_file: bool,
    pub verbose: bool,
    pub regex: bool,
    pub column: bool,
    pub row: bool,
    pub binary: bool,
    pub statistics: bool,
    pub skipped: bool,
    pub interactive: bool,
    pub recursive: bool,
    pub symlink: bool,
    pub color: bool,
    pub file: bool,
    pub skip_vcs: bool,
    pub skip_gitignore: bool,
    pub fixed_order: bool,
    pub parent_ignore: bool,
    pub preserve_time: bool,
    pub tbm: bool,
    pub sse: bool,
    pub max_threads: usize,
    pub size_per_thread: usize,
    pub bin_check_bytes: usize,
    pub mmap_bytes: u64,
}

struct FlagDef {
    id: String,
    long: &'static str,
    short: Option<char>,
    help: &'static str,
    hidden: bool,
}

struct OptDef {
    id: &'static str,
    long: &'static str,
    value_name: &'static str,
    help: &'static str,
    default: String,
}

struct PosDef {
    name: &'static str,
    help: &'static str,
    required: bool,
    multiple: bool,
}

// (long name, enable help, disable help)
const PAIRS: [(&str, &str, &str); 16] = [
    ("regex", "Enable regular expression search", "Disable regular expression search"),
    ("column", "Enable column output", "Disable column output"),
    ("row", "Enable row output", "Disable row output"),
    ("binary", "Enable binary file search", "Disable binary file search"),
    ("statistics", "Enable statistics output", "Disable statistics output"),
    ("skipped", "Enable skipped file output", "Disable skipped file output"),
    ("interactive", "Enable interactive replace", "Disable interactive replace"),
    ("recursive", "Enable recursive directory search", "Disable recursive directory search"),
    ("symlink", "Enable symbolic link follow", "Disable symbolic link follow"),
    ("color", "Enable colored output", "Disable colored output"),
    ("file", "Enable filename output", "Disable filename output"),
    ("skip-vcs", "Enable vcs directory ( .hg/.git/.svn ) skip", "Disable vcs directory ( .hg/.git/.svn ) skip"),
    ("skip-gitignore", "Enable .gitignore skip", "Disable .gitignore skip"),
    ("fixed-order", "Enable output order guarantee", "Disable output order guarantee"),
    ("parent-ignore", "Enable .*ignore file search at parent directories", "Disable .*ignore file search at parent directories"),
    ("preserve-time", "Enable timestamp preserve", "Disable timestamp preserve"),
];

const NO_PREFIX_LONGS: [&str; 16] = [
    "no-regex",
    "no-column",
    "no-row",
    "no-binary",
    "no-statistics",
    "no-skipped",
    "no-interactive",
    "no-recursive",
    "no-symlink",
    "no-color",
    "no-file",
    "no-skip-vcs",
    "no-skip-gitignore",
    "no-fixed-order",
    "no-parent-ignore",
    "no-preserve-time",
];

fn config_value(c: &Config, i: usize) -> bool {
    match i {
        0 => c.regex,
        1 => c.column,
        2 => c.row,
        3 => c.binary,
        4 => c.statistics,
        5 => c.skipped,
        6 => c.interactive,
        7 => c.recursive,
        8 => c.symlink,
        9 => c.color,
        10 => c.file,
        11 => c.skip_vcs,
        12 => c.skip_gitignore,
        13 => c.fixed_order,
        14 => c.parent_ignore,
        15 => c.preserve_time,
        _ => false,
    }
}

pub fn num_cpus() -> usize {
    std::thread::available_parallelism().map(|n| n.get()).unwrap_or(1)
}

struct App {
    bin_name: String,
    flags: Vec<FlagDef>,
    opts: Vec<OptDef>,
    pos: Vec<PosDef>,
}

fn id_of(long: &str) -> String {
    long.replace('-', "_")
}

impl App {
    fn new(bin_name: String, config: &Config) -> App {
        let mut flags = Vec::new();
        flags.push(FlagDef { id: id_of("key-from-file"), long: "key-from-file", short: None, help: "Use file contents of KEYWORD as keyword for search", hidden: false });
        flags.push(FlagDef { id: id_of("rep-from-file"), long: "rep-from-file", short: None, help: "Use file contents of REPLACEMENT as keyword for replacement", hidden: false });
        flags.push(FlagDef { id: id_of("verbose"), long: "verbose", short: None, help: "Verbose message", hidden: false });
        for (i, (long, en, _)) in PAIRS.iter().enumerate() {
            flags.push(FlagDef {
                id: id_of(long),
                long,
                short: if i == 0 { Some('r') } else { None },
                help: en,
                hidden: config_value(config, i),
            });
        }
        for (i, (_, _, dis)) in PAIRS.iter().enumerate() {
            flags.push(FlagDef {
                id: id_of(NO_PREFIX_LONGS[i]),
                long: NO_PREFIX_LONGS[i],
                short: None,
                help: dis,
                hidden: !config_value(config, i),
            });
        }
        flags.push(FlagDef { id: id_of("tbm"), long: "tbm", short: None, help: "[Experimental] Enable TBM matcher", hidden: false });
        flags.push(FlagDef { id: id_of("sse"), long: "sse", short: None, help: "[Experimental] Enable SSE 4.2", hidden: false });
        flags.push(FlagDef { id: "help".to_string(), long: "help", short: Some('h'), help: "Prints help information", hidden: false });
        flags.push(FlagDef { id: "version".to_string(), long: "version", short: Some('V'), help: "Prints version information", hidden: false });

        let opts = vec![
            OptDef { id: "max_threads", long: "max-threads", value_name: "NUM", help: "Number of max threads", default: num_cpus().to_string() },
            OptDef { id: "size_per_thread", long: "size-per-thread", value_name: "BYTES", help: "File size per one thread", default: "1048576".to_string() },
            OptDef { id: "bin_check_bytes", long: "bin-check-bytes", value_name: "BYTES", help: "Read size for checking binary", default: "256".to_string() },
            OptDef { id: "mmap_bytes", long: "mmap-bytes", value_name: "BYTES", help: "[Experimental] Minimum size for using mmap", default: "1048576".to_string() },
        ];
        let pos = vec![
            PosDef { name: "KEYWORD", help: "Keyword for search", required: true, multiple: false },
            PosDef { name: "REPLACEMENT", help: "Keyword for replace", required: true, multiple: false },
            PosDef { name: "PATHS", help: "Search paths", required: false, multiple: true },
        ];
        App { bin_name, flags, opts, pos }
    }

    fn general_usage(&self) -> String {
        format!("{} [FLAGS] [OPTIONS] <KEYWORD> <REPLACEMENT> [PATHS]...", self.bin_name)
    }

    fn display_of(&self, id: &str) -> String {
        if let Some(f) = self.flags.iter().find(|f| f.id == id) {
            return format!("--{}", f.long);
        }
        if let Some(o) = self.opts.iter().find(|o| o.id == id) {
            return format!("--{} <{}>", o.long, o.value_name);
        }
        id.to_string()
    }

    fn smart_usage(&self, used: &[String]) -> String {
        if used.is_empty() {
            return self.general_usage();
        }
        let mut names: Vec<String> = used.to_vec();
        names.sort();
        names.dedup();
        let mut s = format!("{} <KEYWORD> <REPLACEMENT>", self.bin_name);
        for n in names {
            s.push(' ');
            s.push_str(&self.display_of(&n));
        }
        s
    }
}

struct Matched {
    // insertion ordered
    entries: Vec<(String, usize, Vec<String>)>,
}

impl Matched {
    fn get_mut(&mut self, id: &str) -> Option<&mut (String, usize, Vec<String>)> {
        self.entries.iter_mut().find(|e| e.0 == id)
    }
    fn get(&self, id: &str) -> Option<&(String, usize, Vec<String>)> {
        self.entries.iter().find(|e| e.0 == id)
    }
    fn ensure(&mut self, id: &str) -> &mut (String, usize, Vec<String>) {
        if self.get(id).is_none() {
            self.entries.push((id.to_string(), 0, Vec::new()));
        }
        self.get_mut(id).unwrap()
    }
    fn inc(&mut self, id: &str) {
        self.ensure(id).1 += 1;
    }
    fn used(&self) -> Vec<String> {
        self.entries.iter().map(|e| e.0.clone()).collect()
    }
}

struct Painter {
    on: bool,
}

impl Painter {
    fn error(&self, s: &str) -> String {
        if self.on {
            format!("\x1b[1;31m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
    fn warning(&self, s: &str) -> String {
        if self.on {
            format!("\x1b[33m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
    fn good(&self, s: &str) -> String {
        if self.on {
            format!("\x1b[32m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
}

fn term_is_dumb() -> bool {
    std::env::var("TERM").ok().as_deref() == Some("dumb")
}

fn stderr_painter() -> Painter {
    Painter { on: std::io::stderr().is_terminal() && !term_is_dumb() }
}

fn stdout_painter() -> Painter {
    Painter { on: std::io::stdout().is_terminal() && !term_is_dumb() }
}

fn exit_with_error(msg: String) -> ! {
    let mut e = std::io::stderr();
    let _ = e.write_all(msg.as_bytes());
    let _ = e.flush();
    std::process::exit(1);
}

fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    if a == b {
        return 1.0;
    }
    let a_len = a.len();
    let b_len = b.len();
    if a_len == 0 || b_len == 0 || (a_len == 1 && b_len == 1) {
        return 0.0;
    }
    let search_range = (std::cmp::max(a_len, b_len) / 2).saturating_sub(1);
    let mut b_consumed = vec![false; b_len];
    let mut matches = 0.0f64;
    let mut transpositions = 0.0f64;
    let mut b_match_index = 0usize;
    for (i, a_char) in a.iter().enumerate() {
        let min_bound = if i > search_range { i - search_range } else { 0 };
        let max_bound = std::cmp::min(b_len - 1, i + search_range);
        for j in 0..=max_bound {
            if min_bound <= j && *a_char == b[j] && !b_consumed[j] {
                b_consumed[j] = true;
                matches += 1.0;
                if j < b_match_index {
                    transpositions += 1.0;
                }
                b_match_index = j;
                break;
            }
        }
    }
    if matches == 0.0 {
        0.0
    } else {
        (1.0 / 3.0) * ((matches / a_len as f64) + (matches / b_len as f64) + ((matches - transpositions) / matches))
    }
}

fn jaro_winkler(a: &str, b: &str) -> f64 {
    let jd = jaro(a, b);
    let prefix = a.chars().zip(b.chars()).take_while(|(x, y)| x == y).count();
    let d = jd + (0.1 * prefix as f64 * (1.0 - jd));
    if d <= 1.0 {
        d
    } else {
        1.0
    }
}

fn did_you_mean<'a>(v: &str, cands: &[&'a str]) -> Option<&'a str> {
    let mut candidate: Option<(f64, &str)> = None;
    for pv in cands {
        let confidence = jaro_winkler(v, pv);
        if confidence > 0.8 && (candidate.is_none() || candidate.as_ref().unwrap().0 < confidence) {
            candidate = Some((confidence, pv));
        }
    }
    candidate.map(|c| c.1)
}

fn spaces(n: usize) -> String {
    " ".repeat(n)
}

impl App {
    fn help_text(&self, p: &Painter) -> String {
        let mut s = String::new();
        s.push_str(&format!("{} {}\n", p.good(APP_NAME), VERSION));
        if p.on {
            s.push_str("\x1b[33m\nUSAGE:\x1b[0m\n");
        } else {
            s.push_str("\nUSAGE:\n");
        }
        s.push_str(&format!("    {}\n", self.general_usage()));

        // FLAGS
        let vis: Vec<&FlagDef> = self.flags.iter().filter(|f| !f.hidden).collect();
        if p.on {
            s.push_str("\n\x1b[33mFLAGS:\n\x1b[0m");
        } else {
            s.push_str("\nFLAGS:\n");
        }
        let mut longest = 2;
        for f in &vis {
            longest = std::cmp::max(longest, f.long.len() + 2);
        }
        for f in &vis {
            if let Some(c) = f.short {
                s.push_str(&format!("    {}, ", p.good(&format!("-{}", c))));
            } else {
                s.push_str("        ");
            }
            s.push_str(&p.good(&format!("--{}", f.long)));
            s.push_str(&spaces(longest - (f.long.len() + 2) + 4));
            s.push_str(f.help);
            s.push('\n');
        }

        // OPTIONS
        if p.on {
            s.push_str("\n\x1b[33mOPTIONS:\n\x1b[0m");
        } else {
            s.push_str("\nOPTIONS:\n");
        }
        let mut longest = 2;
        for o in &self.opts {
            longest = std::cmp::max(longest, o.long.len() + 2 + 1 + o.value_name.len() + 2);
        }
        for o in &self.opts {
            let w = o.long.len() + 2 + 1 + o.value_name.len() + 2;
            s.push_str("        ");
            s.push_str(&p.good(&format!("--{}", o.long)));
            s.push(' ');
            s.push_str(&p.good(&format!("<{}>", o.value_name)));
            s.push_str(&spaces(longest - w + 4));
            s.push_str(o.help);
            s.push_str(&format!(" [default: {}]", p.good(&o.default)));
            s.push('\n');
        }

        // ARGS
        if p.on {
            s.push_str("\n\x1b[33mARGS:\n\x1b[0m");
        } else {
            s.push_str("\nARGS:\n");
        }
        let disp = |d: &PosDef| -> String {
            if d.multiple {
                format!("<{}>...", d.name)
            } else {
                format!("<{}>", d.name)
            }
        };
        let mut longest = 2;
        for d in &self.pos {
            longest = std::cmp::max(longest, disp(d).len());
        }
        for d in &self.pos {
            let t = disp(d);
            s.push_str("    ");
            s.push_str(&p.good(&t));
            s.push_str(&spaces(longest + 4 - t.len()));
            s.push_str(d.help);
            s.push('\n');
        }
        let _ = self.pos.iter().any(|d| d.required);
        s
    }

    fn print_help(&self) -> ! {
        let p = stdout_painter();
        let text = self.help_text(&p);
        let mut o = std::io::stdout();
        let _ = o.write_all(text.as_bytes());
        let _ = o.flush();
        std::process::exit(0);
    }

    fn print_version(&self) -> ! {
        let mut o = std::io::stdout();
        let _ = o.write_all(format!("{} {}\n", APP_NAME, VERSION).as_bytes());
        let _ = o.flush();
        std::process::exit(0);
    }

    fn usage_block(&self, used: &[String]) -> String {
        format!("USAGE:\n    {}", self.smart_usage(used))
    }

    fn err_unknown(&self, arg: &str, suffix: &str, used: &[String]) -> ! {
        let p = stderr_painter();
        let msg = format!(
            "{} Found argument '{}' which wasn't expected, or isn't valid in this context{}\n\n{}\n\nFor more information try {}\n",
            p.error("error:"),
            p.warning(arg),
            suffix,
            self.usage_block(used),
            p.good("--help")
        );
        exit_with_error(msg)
    }

    fn longs(&self) -> Vec<&'static str> {
        let mut v: Vec<&'static str> = self.flags.iter().map(|f| f.long).collect();
        v.extend(self.opts.iter().map(|o| o.long));
        v
    }
}

pub fn parse(config: &Config) -> Opt {
    let argv: Vec<String> = std::env::args_os().map(|a| a.to_string_lossy().into_owned()).collect();
    let bin_name = argv
        .first()
        .map(|a| {
            std::path::Path::new(a)
                .file_name()
                .map(|f| f.to_string_lossy().into_owned())
                .unwrap_or_else(|| a.clone())
        })
        .unwrap_or_else(|| APP_NAME.to_string());
    let app = App::new(bin_name, config);

    let mut m = Matched { entries: Vec::new() };
    let mut positionals: Vec<String> = Vec::new();
    let mut trailing = false;
    let mut needs_val_of: Option<usize> = None;

    let mut i = 1;
    while i < argv.len() {
        let arg = argv[i].clone();
        i += 1;
        if !trailing {
            if arg.starts_with("--") {
                if arg.len() == 2 {
                    trailing = true;
                    continue;
                }
                let body = arg.trim_start_matches('-');
                let (name, val): (&str, Option<&str>) = if arg.contains('=') {
                    match body.find('=') {
                        Some(pos) => (&body[..pos], Some(&body[pos..])),
                        None => (body, None),
                    }
                } else {
                    (body, None)
                };
                if let Some(oi) = app.opts.iter().position(|o| o.long == name) {
                    let id = app.opts[oi].id;
                    if let Some(v) = val {
                        let v = v.trim_start_matches('=');
                        m.ensure(id).2.push(v.to_string());
                        m.inc(id);
                        needs_val_of = None;
                    } else {
                        m.inc(id);
                        needs_val_of = Some(oi);
                    }
                    continue;
                } else if let Some(f) = app.flags.iter().find(|f| f.long == name) {
                    if f.long == "help" {
                        app.print_help();
                    }
                    if f.long == "version" {
                        app.print_version();
                    }
                    let id = f.id.clone();
                    m.inc(&id);
                    needs_val_of = None;
                    continue;
                } else {
                    let longs = app.longs();
                    let cand = did_you_mean(name, &longs);
                    let mut suffix = String::new();
                    if let Some(c) = cand {
                        suffix = format!("\n\tDid you mean \x1b[32m--\x1b[0m\x1b[32m{}\x1b[0m?", c);
                        if let Some(o) = app.opts.iter().find(|o| o.long == c) {
                            m.ensure(o.id);
                        } else if let Some(f) = app.flags.iter().find(|f| f.long == c) {
                            let id = f.id.clone();
                            m.ensure(&id);
                        }
                    }
                    let used = m.used();
                    app.err_unknown(&format!("--{}", name), &suffix, &used);
                }
            } else if arg.starts_with('-') && arg.len() != 1 {
                let body = arg.trim_start_matches('-');
                for c in body.chars() {
                    if let Some(f) = app.flags.iter().find(|f| f.short == Some(c)) {
                        if c == 'h' {
                            app.print_help();
                        }
                        if c == 'V' {
                            app.print_version();
                        }
                        let id = f.id.clone();
                        m.inc(&id);
                    } else {
                        let used = m.used();
                        app.err_unknown(&format!("-{}", c), "", &used);
                    }
                }
                needs_val_of = None;
                continue;
            }
            if let Some(oi) = needs_val_of {
                let id = app.opts[oi].id;
                m.ensure(id).2.push(arg.clone());
                needs_val_of = None;
                continue;
            }
        }
        positionals.push(arg);
    }

    // add defaults
    for o in &app.opts {
        let e = m.ensure(o.id);
        if e.2.is_empty() {
            e.2.push(o.default.clone());
        }
    }

    // required
    let mut missing = Vec::new();
    if positionals.is_empty() {
        missing.push("<KEYWORD>");
    }
    if positionals.len() < 2 {
        missing.push("<REPLACEMENT>");
    }
    if !missing.is_empty() {
        let p = stderr_painter();
        let mut req = String::new();
        for r in &missing {
            req.push_str(&format!("\n    {}", p.error(r)));
        }
        let used = m.used();
        let msg = format!(
            "{} The following required arguments were not provided:{}\n\n{}\n\nFor more information try {}\n",
            p.error("error:"),
            req,
            app.usage_block(&used),
            p.good("--help")
        );
        exit_with_error(msg);
    }

    // matched args validation
    let used = m.used();
    let mut values: std::collections::HashMap<String, u64> = std::collections::HashMap::new();
    for (id, occ, vals) in &m.entries {
        if let Some(o) = app.opts.iter().find(|o| o.id == id) {
            for v in vals {
                let r: Result<u64, String> = if o.id == "mmap_bytes" {
                    v.parse::<u64>().map_err(|e| e.to_string())
                } else {
                    v.parse::<usize>().map(|x| x as u64).map_err(|e| e.to_string())
                };
                match r {
                    Ok(x) => {
                        values.insert(id.clone(), x);
                    }
                    Err(e) => {
                        let p = stderr_painter();
                        let msg = format!(
                            "{} Invalid value for '{}': {}\n",
                            p.error("error:"),
                            p.warning(&format!("--{} <{}>", o.long, o.value_name)),
                            e
                        );
                        exit_with_error(msg);
                    }
                }
            }
            if *occ > 1 {
                let p = stderr_painter();
                let msg = format!(
                    "{} The argument '{}' was provided more than once, but cannot be used multiple times\n\n{}\n\nFor more information try {}\n",
                    p.error("error:"),
                    p.warning(&format!("--{} <{}>", o.long, o.value_name)),
                    app.usage_block(&used),
                    p.good("--help")
                );
                exit_with_error(msg);
            }
        } else if let Some(f) = app.flags.iter().find(|f| &f.id == id) {
            if *occ > 1 {
                let p = stderr_painter();
                let msg = format!(
                    "{} The argument '{}' was provided more than once, but cannot be used multiple times\n\n{}\n\nFor more information try {}\n",
                    p.error("error:"),
                    p.warning(&format!("--{}", f.long)),
                    app.usage_block(&used),
                    p.good("--help")
                );
                exit_with_error(msg);
            }
        }
    }

    let has = |id: &str| m.get(id).map(|e| e.1 > 0).unwrap_or(false);
    let resolve = |i: usize| -> bool {
        let (long, _, _) = PAIRS[i];
        if config_value(config, i) {
            !has(&id_of(NO_PREFIX_LONGS[i]))
        } else {
            has(&id_of(long))
        }
    };

    let mut opt = Opt::default();
    opt.keyword = positionals[0].clone();
    opt.replacement = positionals[1].clone();
    opt.paths = positionals[2..].to_vec();
    opt.key_from_file = has("key_from_file");
    opt.rep_from_file = has("rep_from_file");
    opt.verbose = has("verbose");
    opt.regex = resolve(0);
    opt.column = resolve(1);
    opt.row = resolve(2);
    opt.binary = resolve(3);
    opt.statistics = resolve(4);
    opt.skipped = resolve(5);
    opt.interactive = resolve(6);
    opt.recursive = resolve(7);
    opt.symlink = resolve(8);
    opt.color = resolve(9);
    opt.file = resolve(10);
    opt.skip_vcs = resolve(11);
    opt.skip_gitignore = resolve(12);
    opt.fixed_order = resolve(13);
    opt.parent_ignore = resolve(14);
    opt.preserve_time = resolve(15);
    opt.tbm = has("tbm");
    opt.sse = has("sse");
    opt.max_threads = *values.get("max_threads").unwrap_or(&1) as usize;
    opt.size_per_thread = *values.get("size_per_thread").unwrap_or(&1048576) as usize;
    opt.bin_check_bytes = *values.get("bin_check_bytes").unwrap_or(&256) as usize;
    opt.mmap_bytes = *values.get("mmap_bytes").unwrap_or(&1048576);
    opt
}
EOF
echo ok"}

actions.command:
cat > /workspace/src/cli.rs <<'EOF'
//! Command line parsing that mimics the behavior of the clap 2 based
//! interface of the original tool.

use crate::config::Config;
use std::io::{IsTerminal, Write};

pub const VERSION: &str = "0.6.0";
pub const APP_NAME: &str = "ambr";

#[derive(Debug, Default, Clone)]
pub struct Opt {
    pub keyword: String,
    pub replacement: String,
    pub paths: Vec<String>,
    pub key_from_file: bool,
    pub rep_from_file: bool,
    pub verbose: bool,
    pub regex: bool,
    pub column: bool,
    pub row: bool,
    pub binary: bool,
    pub statistics: bool,
    pub skipped: bool,
    pub interactive: bool,
    pub recursive: bool,
    pub symlink: bool,
    pub color: bool,
    pub file: bool,
    pub skip_vcs: bool,
    pub skip_gitignore: bool,
    pub fixed_order: bool,
    pub parent_ignore: bool,
    pub preserve_time: bool,
    pub tbm: bool,
    pub sse: bool,
    pub max_threads: usize,
    pub size_per_thread: usize,
    pub bin_check_bytes: usize,
    pub mmap_bytes: u64,
}

struct FlagDef {
    id: String,
    long: &'static str,
    short: Option<char>,
    help: &'static str,
    hidden: bool,
}

struct OptDef {
    id: &'static str,
    long: &'static str,
    value_name: &'static str,
    help: &'static str,
    default: String,
}

struct PosDef {
    name: &'static str,
    help: &'static str,
    required: bool,
    multiple: bool,
}

// (long name, enable help, disable help)
const PAIRS: [(&str, &str, &str); 16] = [
    ("regex", "Enable regular expression search", "Disable regular expression search"),
    ("column", "Enable column output", "Disable column output"),
    ("row", "Enable row output", "Disable row output"),
    ("binary", "Enable binary file search", "Disable binary file search"),
    ("statistics", "Enable statistics output", "Disable statistics output"),
    ("skipped", "Enable skipped file output", "Disable skipped file output"),
    ("interactive", "Enable interactive replace", "Disable interactive replace"),
    ("recursive", "Enable recursive directory search", "Disable recursive directory search"),
    ("symlink", "Enable symbolic link follow", "Disable symbolic link follow"),
    ("color", "Enable colored output", "Disable colored output"),
    ("file", "Enable filename output", "Disable filename output"),
    ("skip-vcs", "Enable vcs directory ( .hg/.git/.svn ) skip", "Disable vcs directory ( .hg/.git/.svn ) skip"),
    ("skip-gitignore", "Enable .gitignore skip", "Disable .gitignore skip"),
    ("fixed-order", "Enable output order guarantee", "Disable output order guarantee"),
    ("parent-ignore", "Enable .*ignore file search at parent directories", "Disable .*ignore file search at parent directories"),
    ("preserve-time", "Enable timestamp preserve", "Disable timestamp preserve"),
];

const NO_PREFIX_LONGS: [&str; 16] = [
    "no-regex",
    "no-column",
    "no-row",
    "no-binary",
    "no-statistics",
    "no-skipped",
    "no-interactive",
    "no-recursive",
    "no-symlink",
    "no-color",
    "no-file",
    "no-skip-vcs",
    "no-skip-gitignore",
    "no-fixed-order",
    "no-parent-ignore",
    "no-preserve-time",
];

fn config_value(c: &Config, i: usize) -> bool {
    match i {
        0 => c.regex,
        1 => c.column,
        2 => c.row,
        3 => c.binary,
        4 => c.statistics,
        5 => c.skipped,
        6 => c.interactive,
        7 => c.recursive,
        8 => c.symlink,
        9 => c.color,
        10 => c.file,
        11 => c.skip_vcs,
        12 => c.skip_gitignore,
        13 => c.fixed_order,
        14 => c.parent_ignore,
        15 => c.preserve_time,
        _ => false,
    }
}

pub fn num_cpus() -> usize {
    std::thread::available_parallelism().map(|n| n.get()).unwrap_or(1)
}

struct App {
    bin_name: String,
    flags: Vec<FlagDef>,
    opts: Vec<OptDef>,
    pos: Vec<PosDef>,
}

fn id_of(long: &str) -> String {
    long.replace('-', "_")
}

impl App {
    fn new(bin_name: String, config: &Config) -> App {
        let mut flags = Vec::new();
        flags.push(FlagDef { id: id_of("key-from-file"), long: "key-from-file", short: None, help: "Use file contents of KEYWORD as keyword for search", hidden: false });
        flags.push(FlagDef { id: id_of("rep-from-file"), long: "rep-from-file", short: None, help: "Use file contents of REPLACEMENT as keyword for replacement", hidden: false });
        flags.push(FlagDef { id: id_of("verbose"), long: "verbose", short: None, help: "Verbose message", hidden: false });
        for (i, (long, en, _)) in PAIRS.iter().enumerate() {
            flags.push(FlagDef {
                id: id_of(long),
                long,
                short: if i == 0 { Some('r') } else { None },
                help: en,
                hidden: config_value(config, i),
            });
        }
        for (i, (_, _, dis)) in PAIRS.iter().enumerate() {
            flags.push(FlagDef {
                id: id_of(NO_PREFIX_LONGS[i]),
                long: NO_PREFIX_LONGS[i],
                short: None,
                help: dis,
                hidden: !config_value(config, i),
            });
        }
        flags.push(FlagDef { id: id_of("tbm"), long: "tbm", short: None, help: "[Experimental] Enable TBM matcher", hidden: false });
        flags.push(FlagDef { id: id_of("sse"), long: "sse", short: None, help: "[Experimental] Enable SSE 4.2", hidden: false });
        flags.push(FlagDef { id: "help".to_string(), long: "help", short: Some('h'), help: "Prints help information", hidden: false });
        flags.push(FlagDef { id: "version".to_string(), long: "version", short: Some('V'), help: "Prints version information", hidden: false });

        let opts = vec![
            OptDef { id: "max_threads", long: "max-threads", value_name: "NUM", help: "Number of max threads", default: num_cpus().to_string() },
            OptDef { id: "size_per_thread", long: "size-per-thread", value_name: "BYTES", help: "File size per one thread", default: "1048576".to_string() },
            OptDef { id: "bin_check_bytes", long: "bin-check-bytes", value_name: "BYTES", help: "Read size for checking binary", default: "256".to_string() },
            OptDef { id: "mmap_bytes", long: "mmap-bytes", value_name: "BYTES", help: "[Experimental] Minimum size for using mmap", default: "1048576".to_string() },
        ];
        let pos = vec![
            PosDef { name: "KEYWORD", help: "Keyword for search", required: true, multiple: false },
            PosDef { name: "REPLACEMENT", help: "Keyword for replace", required: true, multiple: false },
            PosDef { name: "PATHS", help: "Search paths", required: false, multiple: true },
        ];
        App { bin_name, flags, opts, pos }
    }

    fn general_usage(&self) -> String {
        format!("{} [FLAGS] [OPTIONS] <KEYWORD> <REPLACEMENT> [PATHS]...", self.bin_name)
    }

    fn display_of(&self, id: &str) -> String {
        if let Some(f) = self.flags.iter().find(|f| f.id == id) {
            return format!("--{}", f.long);
        }
        if let Some(o) = self.opts.iter().find(|o| o.id == id) {
            return format!("--{} <{}>", o.long, o.value_name);
        }
        id.to_string()
    }

    fn smart_usage(&self, used: &[String]) -> String {
        if used.is_empty() {
            return self.general_usage();
        }
        let mut names: Vec<String> = used.to_vec();
        names.sort();
        names.dedup();
        let mut s = format!("{} <KEYWORD> <REPLACEMENT>", self.bin_name);
        for n in names {
            s.push(' ');
            s.push_str(&self.display_of(&n));
        }
        s
    }
}

struct Matched {
    // insertion ordered
    entries: Vec<(String, usize, Vec<String>)>,
}

impl Matched {
    fn get_mut(&mut self, id: &str) -> Option<&mut (String, usize, Vec<String>)> {
        self.entries.iter_mut().find(|e| e.0 == id)
    }
    fn get(&self, id: &str) -> Option<&(String, usize, Vec<String>)> {
        self.entries.iter().find(|e| e.0 == id)
    }
    fn ensure(&mut self, id: &str) -> &mut (String, usize, Vec<String>) {
        if self.get(id).is_none() {
            self.entries.push((id.to_string(), 0, Vec::new()));
        }
        self.get_mut(id).unwrap()
    }
    fn inc(&mut self, id: &str) {
        self.ensure(id).1 += 1;
    }
    fn used(&self) -> Vec<String> {
        self.entries.iter().map(|e| e.0.clone()).collect()
    }
}

struct Painter {
    on: bool,
}

impl Painter {
    fn error(&self, s: &str) -> String {
        if self.on {
            format!("\x1b[1;31m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
    fn warning(&self, s: &str) -> String {
        if self.on {
            format!("\x1b[33m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
    fn good(&self, s: &str) -> String {
        if self.on {
            format!("\x1b[32m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
}

fn term_is_dumb() -> bool {
    std::env::var("TERM").ok().as_deref() == Some("dumb")
}

fn stderr_painter() -> Painter {
    Painter { on: std::io::stderr().is_terminal() && !term_is_dumb() }
}

fn stdout_painter() -> Painter {
    Painter { on: std::io::stdout().is_terminal() && !term_is_dumb() }
}

fn exit_with_error(msg: String) -> ! {
    let mut e = std::io::stderr();
    let _ = e.write_all(msg.as_bytes());
    let _ = e.flush();
    std::process::exit(1);
}

fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    if a == b {
        return 1.0;
    }
    let a_len = a.len();
    let b_len = b.len();
    if a_len == 0 || b_len == 0 || (a_len == 1 && b_len == 1) {
        return 0.0;
    }
    let search_range = (std::cmp::max(a_len, b_len) / 2).saturating_sub(1);
    let mut b_consumed = vec![false; b_len];
    let mut matches = 0.0f64;
    let mut transpositions = 0.0f64;
    let mut b_match_index = 0usize;
    for (i, a_char) in a.iter().enumerate() {
        let min_bound = if i > search_range { i - search_range } else { 0 };
        let max_bound = std::cmp::min(b_len - 1, i + search_range);
        for j in 0..=max_bound {
            if min_bound <= j && *a_char == b[j] && !b_consumed[j] {
                b_consumed[j] = true;
                matches += 1.0;
                if j < b_match_index {
                    transpositions += 1.0;
                }
                b_match_index = j;
                break;
            }
        }
    }
    if matches == 0.0 {
        0.0
    } else {
        (1.0 / 3.0) * ((matches / a_len as f64) + (matches / b_len as f64) + ((matches - transpositions) / matches))
    }
}

fn jaro_winkler(a: &str, b: &str) -> f64 {
    let jd = jaro(a, b);
    let prefix = a.chars().zip(b.chars()).take_while(|(x, y)| x == y).count();
    let d = jd + (0.1 * prefix as f64 * (1.0 - jd));
    if d <= 1.0 {
        d
    } else {
        1.0
    }
}

fn did_you_mean<'a>(v: &str, cands: &[&'a str]) -> Option<&'a str> {
    let mut candidate: Option<(f64, &str)> = None;
    for pv in cands {
        let confidence = jaro_winkler(v, pv);
        if confidence > 0.8 && (candidate.is_none() || candidate.as_ref().unwrap().0 < confidence) {
            candidate = Some((confidence, pv));
        }
    }
    candidate.map(|c| c.1)
}

fn spaces(n: usize) -> String {
    " ".repeat(n)
}

impl App {
    fn help_text(&self, p: &Painter) -> String {
        let mut s = String::new();
        s.push_str(&format!("{} {}\n", p.good(APP_NAME), VERSION));
        if p.on {
            s.push_str("\x1b[33m\nUSAGE:\x1b[0m\n");
        } else {
            s.push_str("\nUSAGE:\n");
        }
        s.push_str(&format!("    {}\n", self.general_usage()));

        // FLAGS
        let vis: Vec<&FlagDef> = self.flags.iter().filter(|f| !f.hidden).collect();
        if p.on {
            s.push_str("\n\x1b[33mFLAGS:\n\x1b[0m");
        } else {
            s.push_str("\nFLAGS:\n");
        }
        let mut longest = 2;
        for f in &vis {
            longest = std::cmp::max(longest, f.long.len() + 2);
        }
        for f in &vis {
            if let Some(c) = f.short {
                s.push_str(&format!("    {}, ", p.good(&format!("-{}", c))));
            } else {
                s.push_str("        ");
            }
            s.push_str(&p.good(&format!("--{}", f.long)));
            s.push_str(&spaces(longest - (f.long.len() + 2) + 4));
            s.push_str(f.help);
            s.push('\n');
        }

        // OPTIONS
        if p.on {
            s.push_str("\n\x1b[33mOPTIONS:\n\x1b[0m");
        } else {
            s.push_str("\nOPTIONS:\n");
        }
        let mut longest = 2;
        for o in &self.opts {
            longest = std::cmp::max(longest, o.long.len() + 2 + 1 + o.value_name.len() + 2);
        }
        for o in &self.opts {
            let w = o.long.len() + 2 + 1 + o.value_name.len() + 2;
            s.push_str("        ");
            s.push_str(&p.good(&format!("--{}", o.long)));
            s.push(' ');
            s.push_str(&p.good(&format!("<{}>", o.value_name)));
            s.push_str(&spaces(longest - w + 4));
            s.push_str(o.help);
            s.push_str(&format!(" [default: {}]", p.good(&o.default)));
            s.push('\n');
        }

        // ARGS
        if p.on {
            s.push_str("\n\x1b[33mARGS:\n\x1b[0m");
        } else {
            s.push_str("\nARGS:\n");
        }
        let disp = |d: &PosDef| -> String {
            if d.multiple {
                format!("<{}>...", d.name)
            } else {
                format!("<{}>", d.name)
            }
        };
        let mut longest = 2;
        for d in &self.pos {
            longest = std::cmp::max(longest, disp(d).len());
        }
        for d in &self.pos {
            let t = disp(d);
            s.push_str("    ");
            s.push_str(&p.good(&t));
            s.push_str(&spaces(longest + 4 - t.len()));
            s.push_str(d.help);
            s.push('\n');
        }
        let _ = self.pos.iter().any(|d| d.required);
        s
    }

    fn print_help(&self) -> ! {
        let p = stdout_painter();
        let text = self.help_text(&p);
        let mut o = std::io::stdout();
        let _ = o.write_all(text.as_bytes());
        let _ = o.flush();
        std::process::exit(0);
    }

    fn print_version(&self) -> ! {
        let mut o = std::io::stdout();
        let _ = o.write_all(format!("{} {}\n", APP_NAME, VERSION).as_bytes());
        let _ = o.flush();
        std::process::exit(0);
    }

    fn usage_block(&self, used: &[String]) -> String {
        format!("USAGE:\n    {}", self.smart_usage(used))
    }

    fn err_unknown(&self, arg: &str, suffix: &str, used: &[String]) -> ! {
        let p = stderr_painter();
        let msg = format!(
            "{} Found argument '{}' which wasn't expected, or isn't valid in this context{}\n\n{}\n\nFor more information try {}\n",
            p.error("error:"),
            p.warning(arg),
            suffix,
            self.usage_block(used),
            p.good("--help")
        );
        exit_with_error(msg)
    }

    fn longs(&self) -> Vec<&'static str> {
        let mut v: Vec<&'static str> = self.flags.iter().map(|f| f.long).collect();
        v.extend(self.opts.iter().map(|o| o.long));
        v
    }
}

pub fn parse(config: &Config) -> Opt {
    let argv: Vec<String> = std::env::args_os().map(|a| a.to_string_lossy().into_owned()).collect();
    let bin_name = argv
        .first()
        .map(|a| {
            std::path::Path::new(a)
                .file_name()
                .map(|f| f.to_string_lossy().into_owned())
                .unwrap_or_else(|| a.clone())
        })
        .unwrap_or_else(|| APP_NAME.to_string());
    let app = App::new(bin_name, config);

    let mut m = Matched { entries: Vec::new() };
    let mut positionals: Vec<String> = Vec::new();
    let mut trailing = false;
    let mut needs_val_of: Option<usize> = None;

    let mut i = 1;
    while i < argv.len() {
        let arg = argv[i].clone();
        i += 1;
        if !trailing {
            if arg.starts_with("--") {
                if arg.len() == 2 {
                    trailing = true;
                    continue;
                }
                let body = arg.trim_start_matches('-');
                let (name, val): (&str, Option<&str>) = if arg.contains('=') {
                    match body.find('=') {
                        Some(pos) => (&body[..pos], Some(&body[pos..])),
                        None => (body, None),
                    }
                } else {
                    (body, None)
                };
                if let Some(oi) = app.opts.iter().position(|o| o.long == name) {
                    let id = app.opts[oi].id;
                    if let Some(v) = val {
                        let v = v.trim_start_matches('=');
                        m.ensure(id).2.push(v.to_string());
                        m.inc(id);
                        needs_val_of = None;
                    } else {
                        m.inc(id);
                        needs_val_of = Some(oi);
                    }
                    continue;
                } else if let Some(f) = app.flags.iter().find(|f| f.long == name) {
                    if f.long == "help" {
                        app.print_help();
                    }
                    if f.long == "version" {
                        app.print_version();
                    }
                    let id = f.id.clone();
                    m.inc(&id);
                    needs_val_of = None;
                    continue;
                } else {
                    let longs = app.longs();
                    let cand = did_you_mean(name, &longs);
                    let mut suffix = String::new();
                    if let Some(c) = cand {
                        suffix = format!("\n\tDid you mean \x1b[32m--\x1b[0m\x1b[32m{}\x1b[0m?", c);
                        if let Some(o) = app.opts.iter().find(|o| o.long == c) {
                            m.ensure(o.id);
                        } else if let Some(f) = app.flags.iter().find(|f| f.long == c) {
                            let id = f.id.clone();
                            m.ensure(&id);
                        }
                    }
                    let used = m.used();
                    app.err_unknown(&format!("--{}", name), &suffix, &used);
                }
            } else if arg.starts_with('-') && arg.len() != 1 {
                let body = arg.trim_start_matches('-');
                for c in body.chars() {
                    if let Some(f) = app.flags.iter().find(|f| f.short == Some(c)) {
                        if c == 'h' {
                            app.print_help();
                        }
                        if c == 'V' {
                            app.print_version();
                        }
                        let id = f.id.clone();
                        m.inc(&id);
                    } else {
                        let used = m.used();
                        app.err_unknown(&format!("-{}", c), "", &used);
                    }
                }
                needs_val_of = None;
                continue;
            }
            if let Some(oi) = needs_val_of {
                let id = app.opts[oi].id;
                m.ensure(id).2.push(arg.clone());
                needs_val_of = None;
                continue;
            }
        }
        positionals.push(arg);
    }

    // add defaults
    for o in &app.opts {
        let e = m.ensure(o.id);
        if e.2.is_empty() {
            e.2.push(o.default.clone());
        }
    }

    // required
    let mut missing = Vec::new();
    if positionals.is_empty() {
        missing.push("<KEYWORD>");
    }
    if positionals.len() < 2 {
        missing.push("<REPLACEMENT>");
    }
    if !missing.is_empty() {
        let p = stderr_painter();
        let mut req = String::new();
        for r in &missing {
            req.push_str(&format!("\n    {}", p.error(r)));
        }
        let used = m.used();
        let msg = format!(
            "{} The following required arguments were not provided:{}\n\n{}\n\nFor more information try {}\n",
            p.error("error:"),
            req,
            app.usage_block(&used),
            p.good("--help")
        );
        exit_with_error(msg);
    }

    // matched args validation
    let used = m.used();
    let mut values: std::collections::HashMap<String, u64> = std::collections::HashMap::new();
    for (id, occ, vals) in &m.entries {
        if let Some(o) = app.opts.iter().find(|o| o.id == id) {
            for v in vals {
                let r: Result<u64, String> = if o.id == "mmap_bytes" {
                    v.parse::<u64>().map_err(|e| e.to_string())
                } else {
                    v.parse::<usize>().map(|x| x as u64).map_err(|e| e.to_string())
                };
                match r {
                    Ok(x) => {
                        values.insert(id.clone(), x);
                    }
                    Err(e) => {
                        let p = stderr_painter();
                        let msg = format!(
                            "{} Invalid value for '{}': {}\n",
                            p.error("error:"),
                            p.warning(&format!("--{} <{}>", o.long, o.value_name)),
                            e
                        );
                        exit_with_error(msg);
                    }
                }
            }
            if *occ > 1 {
                let p = stderr_painter();
                let msg = format!(
                    "{} The argument '{}' was provided more than once, but cannot be used multiple times\n\n{}\n\nFor more information try {}\n",
                    p.error("error:"),
                    p.warning(&format!("--{} <{}>", o.long, o.value_name)),
                    app.usage_block(&used),
                    p.good("--help")
                );
                exit_with_error(msg);
            }
        } else if let Some(f) = app.flags.iter().find(|f| &f.id == id) {
            if *occ > 1 {
                let p = stderr_painter();
                let msg = format!(
                    "{} The argument '{}' was provided more than once, but cannot be used multiple times\n\n{}\n\nFor more information try {}\n",
                    p.error("error:"),
                    p.warning(&format!("--{}", f.long)),
                    app.usage_block(&used),
                    p.good("--help")
                );
                exit_with_error(msg);
            }
        }
    }

    let has = |id: &str| m.get(id).map(|e| e.1 > 0).unwrap_or(false);
    let resolve = |i: usize| -> bool {
        let (long, _, _) = PAIRS[i];
        if config_value(config, i) {
            !has(&id_of(NO_PREFIX_LONGS[i]))
        } else {
            has(&id_of(long))
        }
    };

    let mut opt = Opt::default();
    opt.keyword = positionals[0].clone();
    opt.replacement = positionals[1].clone();
    opt.paths = positionals[2..].to_vec();
    opt.key_from_file = has("key_from_file");
    opt.rep_from_file = has("rep_from_file");
    opt.verbose = has("verbose");
    opt.regex = resolve(0);
    opt.column = resolve(1);
    opt.row = resolve(2);
    opt.binary = resolve(3);
    opt.statistics = resolve(4);
    opt.skipped = resolve(5);
    opt.interactive = resolve(6);
    opt.recursive = resolve(7);
    opt.symlink = resolve(8);
    opt.color = resolve(9);
    opt.file = resolve(10);
    opt.skip_vcs = resolve(11);
    opt.skip_gitignore = resolve(12);
    opt.fixed_order = resolve(13);
    opt.parent_ignore = resolve(14);
    opt.preserve_time = resolve(15);
    opt.tbm = has("tbm");
    opt.sse = has("sse");
    opt.max_threads = *values.get("max_threads").unwrap_or(&1) as usize;
    opt.size_per_thread = *values.get("size_per_thread").unwrap_or(&1048576) as usize;
    opt.bin_check_bytes = *values.get("bin_check_bytes").unwrap_or(&256) as usize;
    opt.mmap_bytes = *values.get("mmap_bytes").unwrap_or(&1048576);
    opt
}
EOF
echo ok

