//! Directory traversal.

use crate::cli::Opt;
use ignore::gitignore::Gitignore;
use std::collections::HashSet;
use std::fs;
use std::path::{Path, PathBuf};

pub struct FoundFile {
    pub path: PathBuf,
    pub real: PathBuf,
}

pub struct Finder<'a> {
    opt: &'a Opt,
    pub infos: Vec<String>,
    pub errors: Vec<String>,
    pub files: Vec<FoundFile>,
    seen: HashSet<PathBuf>,
    current_ignore: Option<Gitignore>,
}

const VCS_DIRS: [&str; 4] = [".git", ".hg", ".svn", ".bzr"];

fn ignored(gi: &Option<Gitignore>, path: &Path, is_dir: bool) -> bool {
    match gi {
        Some(g) => g.matched(path, is_dir).is_ignore(),
        None => false,
    }
}

impl<'a> Finder<'a> {
    pub fn new(opt: &'a Opt) -> Finder<'a> {
        Finder {
            opt,
            infos: Vec::new(),
            errors: Vec::new(),
            files: Vec::new(),
            seen: HashSet::new(),
            current_ignore: None,
        }
    }

    fn info(&mut self, msg: String) {
        if self.opt.skipped || self.opt.verbose {
            self.infos.push(msg);
        }
    }

    fn error(&mut self, msg: String) {
        self.errors.push(msg);
    }

    pub fn run(&mut self, paths: &[PathBuf]) {
        for p in paths {
            if self.opt.skip_gitignore && self.opt.parent_ignore {
                self.parent_search(p);
            }
            self.walk(p);
        }
    }

    fn parent_search(&mut self, path: &Path) {
        let md = match fs::metadata(path) {
            Ok(m) => m,
            Err(e) => {
                self.error(format!("Error: {} @ {}", e, path.display()));
                return;
            }
        };
        let mut base: PathBuf = if md.is_dir() {
            path.join("..")
        } else {
            match path.parent() {
                Some(p) => p.to_path_buf(),
                None => return,
            }
        };
        let mut guard = 0;
        loop {
