/// Read a single byte from stdin with canonical mode and echo disabled.
pub fn getch() -> u8 {
    let mut orig: libc::termios = unsafe { std::mem::zeroed() };
    let have = unsafe { libc::tcgetattr(0, &mut orig) } == 0;
    if have {
        let mut raw = orig;
        raw.c_lflag &= !(libc::ICANON | libc::ECHO);
        if let Ok(mut g) = SAVED_TERMIOS.lock() {
            *g = Some(orig);
        }
        unsafe {
            libc::tcsetattr(0, libc::TCSADRAIN, &raw);
        }
    }
    let mut buf = [0u8; 1];
    loop {
        let r = unsafe { libc::read(0, buf.as_mut_ptr() as *mut libc::c_void, 1) };
        if r < 0 {
            let err = std::io::Error::last_os_error();
            if err.kind() == std::io::ErrorKind::Interrupted {
                continue;
            }
        }
        break;
    }
    if have {
        restore_terminal();
    }
    buf[0]
}

static PIPE_W: std::sync::atomic::AtomicI32 = std::sync::atomic::AtomicI32::new(-1);

