    let fd = PIPE_W.load(std::sync::atomic::Ordering::SeqCst);
    if fd >= 0 {
        let b = [1u8];
        unsafe {
            libc::write(fd, b.as_ptr() as *const libc::c_void, 1);
        }
    }
}

