pub fn install_handler<F: FnOnce() + Send + 'static>(f: F) {
    if INSTALLED.swap(true, std::sync::atomic::Ordering::SeqCst) {
        return;
    }
    let mut fds = [0i32; 2];
    if unsafe { libc::pipe(fds.as_mut_ptr()) } != 0 {
        return;
    }
    PIPE_W.store(fds[1], std::sync::atomic::Ordering::SeqCst);
    let rfd = fds[0];
    std::thread::spawn(move || {
        let mut b = [0u8; 1];
        loop {
            let r = unsafe { libc::read(rfd, b.as_mut_ptr() as *mut libc::c_void, 1) };
            if r == 1 {
                break;
            }
            if r < 0 {
                let err = std::io::Error::last_os_error();
                if err.kind() == std::io::ErrorKind::Interrupted {
                    continue;
