use cli::Opt;
use console::{Console, Stream, CYAN, GREEN, RED, WHITE, YELLOW};
use std::fs;
use std::io::{Read, Write};
use std::path::{Path, PathBuf};
use std::time::{Duration, Instant};
use unicode_width::UnicodeWidthStr;

fn gettid() -> i64 {
    unsafe { libc::syscall(libc::SYS_gettid) as i64 }
}

fn emulate_panic(thread: &str, location: &str, msg: &str) {
    let _ = std::io::stdout().flush();
    let text = format!(
        "\nthread '{}' ({}) panicked at {}:\n{}\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n",
        thread,
        gettid(),
        location,
        msg
    );
    let mut e = std::io::stderr();
    let _ = e.write_all(text.as_bytes());
    let _ = e.flush();
}

fn hang() -> ! {
    let _ = std::io::stdout().flush();
    loop {
        std::thread::sleep(Duration::from_secs(3600));
    }
}

fn escape(s: &str) -> String {
    s.replace("\\n", "\n").replace("\\r", "\r").replace("\\t", "\t").replace("\\\\", "\\")
}

fn read_arg_file(path: &str, check_empty: bool, out: &mut Console, err: &mut Console) -> String {
    let mut f = match fs::File::open(path) {
        Ok(f) => f,
        Err(_) => {
            err.write(RED, &format!("Error: file not found @ {:?}\n", path));
            out.reset();
            err.reset();
            console::fatal_exit(1);
        }
    };
    let mut s = String::new();
    let _ = f.read_to_string(&mut s);
    if check_empty && s.is_empty() {
        err.write(RED, &format!("Error: file is empty @ {:?}\n", path));
        out.reset();
        err.reset();
        console::fatal_exit(1);
    }
    s
}

struct Matcher {
    keyword: Vec<u8>,
    regex: Option<regex::Regex>,
    is_regex: bool,
    tbm: bool,
}

enum MatchOutcome {
    Skip,
    Found(Vec<(usize, usize)>, usize),
}

impl Matcher {
    fn search(&self, opt: &Opt, path: &Path, infos: &mut Vec<String>, errors: &mut Vec<String>) -> MatchOutcome {
        let data = match fs::read(path) {
            Ok(d) => d,
            Err(e) => {
                errors.push(format!("Error: {} @ {:?}\n", e.kind(), path));
                return MatchOutcome::Skip;
            }
        };
        if data.is_empty() {
            return MatchOutcome::Skip;
        }
        if !opt.binary {
            let n = std::cmp::min(opt.bin_check_bytes, data.len());
            if data[..n].iter().any(|&b| b <= 0x08) {
                if opt.skipped || opt.verbose {
                    infos.push(format!("Skip (binary)    : {:?}", path));
                }
                return MatchOutcome::Skip;
            }
        }
        let mut found = Vec::new();
        if self.is_regex {
            if let Some(re) = &self.regex {
                if let Ok(s) = std::str::from_utf8(&data) {
                    for m in re.find_iter(s) {
                        found.push((m.start(), m.end()));
                    }
                }
            }
        } else {
            if self.keyword.is_empty() {
                if self.tbm {
                    return MatchOutcome::Found(found, data.len());
                }
                hang();
            }
            for pos in memchr::memmem::find_iter(&data, &self.keyword) {
                found.push((pos, pos + self.keyword.len()));
            }
        }
        MatchOutcome::Found(found, data.len())
    }
}

#[derive(PartialEq)]
enum Answer {
    Yes,
    No,
    All,
    Quit,
}

struct Replacer<'a> {
    opt: &'a Opt,
    replacement: String,
    stripped_keyword: String,
    all: bool,
}

fn lossy(b: &[u8]) -> String {
    String::from_utf8_lossy(b).into_owned()
}

fn ask(out: &mut Console) -> Answer {
    loop {
        out.write(CYAN, "Replace keyword? [Y]es/[n]o/[a]ll/[q]uit: ");
        out.flush();
        let b = input::getch();
        let ch = b as char;
        let mut s = String::new();
        s.push(ch);
        if ch != '\n' {
            s.push('\n');
        }
        out.write(CYAN, &s);
        out.flush();
        match ch {
            'y' | 'Y' | '\n' | '\r' => return Answer::Yes,
            'n' | 'N' => return Answer::No,
            'a' | 'A' => return Answer::All,
            'q' | 'Q' => return Answer::Quit,
            _ => {}
        }
    }
}

impl<'a> Replacer<'a> {
    fn compute_rep(&self, matched: &[u8]) -> Result<Vec<u8>, (&'static str, String)> {
        if !self.opt.regex {
            return Ok(self.replacement.as_bytes().to_vec());
        }
        let re = match regex::Regex::new(&self.stripped_keyword) {
            Ok(r) => r,
            Err(e) => {
                return Err((
