    /// Display a match. Returns false if the display failed (emulated panic).
    fn display(&self, out: &mut Console, path: &Path, src: &[u8], s: usize, e: usize, rep: &[u8]) -> bool {
        let len = src.len();
        if s >= len && len > 0 {
            emulate_panic(
                "replacer",
                "src/console.rs:105:16",
                &format!("index out of bounds: the len is {} but the index is {}", len, s),
            );
            return false;
        }
        let mut beg = s;
        while beg > 0 {
            if src[beg] == b'\n' || src[beg] == b'\r' {
                beg += 1;
                break;
            }
            beg -= 1;
        }
        let mut end = e;
        while end < len {
            if src[end] == b'\n' || src[end] == b'\r' {
                break;
            }
            end += 1;
        }
        let pre = &src[..s];
        let line = pre.iter().filter(|&&b| b == b'\n').count() + 1;
        let last_nl = pre.iter().rposition(|&b| b == b'\n').unwrap_or(0);
        let col = s - last_nl;

        let mut width = 0;
        let mut rest = String::new();
        if self.opt.file {
            let p = path.display().to_string();
            out.write(GREEN, &p);
            width += UnicodeWidthStr::width(p.as_str());
            rest.push_str(": ");
