            rest.push_str(&format!("{}:", line));
        }
        if self.opt.row {
            rest.push_str(&format!("{}:", col));
        }
        width += UnicodeWidthStr::width(rest.as_str());
        if width < 4 {
            rest.push_str(&" ".repeat(4 - width));
            width = 4;
        }
        out.write(CYAN, &rest);
        if beg < s {
            out.write(WHITE, &lossy(&src[beg..s]));
        }
        out.write(YELLOW, &lossy(&src[s..e]));
