            v1_path = Some(path.to_string());
        }
    }
    let ceil = |q: f64, p: f64| -> Option<usize> {
        if p <= 0.0 || q <= 0.0 {
            None
        } else {
            Some((q / p).ceil() as usize)
        }
    };
    if let Some(p) = v2_path {
