                let q = it.next()?;
                if q == "max" {
                    return None;
                }
                let per = it.next().unwrap_or("100000");
                return ceil(q.parse().ok()?, per.parse().ok()?);
            }
        }
    }
    if let Some(p) = v1_path {
        for base in ["/sys/fs/cgroup/cpu,cpuacct", "/sys/fs/cgroup/cpu"] {
            for sub in [p.trim_end_matches('/').to_string(), String::new()] {
