                let per = read_trim(&format!("{}{}/cpu.cfs_period_us", base, sub));
                if let (Some(q), Some(per)) = (q, per) {
                    let q: f64 = q.parse().ok()?;
                    if q < 0.0 {
                        return None;
                    }
                    return ceil(q, per.parse().ok()?);
                }
            }
        }
    }
    None
}

